": "20-06-2026", "type": "Expense", "amount": 5000.0, "description": "بچوں کی روٹی کے لیے", "donor_name": "", "head_name": "", "final_serial": 211}, {"source": "File2_119", "orig_id": 118, "date": "2026-06-24", "raw_date": "24-06-2026", "type": "Expense", "amount": 5000.0, "description": "بچوں کی روٹی کے لیے", "donor_name": "", "head_name": "", "final_serial": 212}, {"source": "File2_119", "orig_id": 19, "date": "2026-07-22", "raw_date": "22-07-2026", "type": "Income", "amount": 200000.0, "description": "مد: عطیہ | نام: ڈاکٹر عبدالحکیم عاطف صاحب بتوسط قاری حماد اللہ ساجد | تفصیل: ڈاکٹر عبدالحکیم عاطف صاحب بتوسط قاری حماد اللہ ساجد", "donor_name": "ڈاکٹر عبدالحکیم عاطف صاحب بتوسط قاری حماد اللہ ساجد", "head_name": "صدقات", "final_serial": 213}, {"source": "File2_119", "orig_id": 119, "date": "2026-07-25", "raw_date": "25-07-2026", "type": "Expense", "amount": 10000.0, "description": "مولانا قاری حماد اللہ ساجد صاحب کی کلاس فیس ادا کی گئی", "donor_name": "", "head_name": "صدقات", "final_serial": 214}]
