// 3. رسید نمبر کا پیٹرن تنزیل کے یوزر آئی ڈی کے مطابق جنریٹ کریں (تاریخی ترتیب سے)
$receipt_base = $target_user_id * 100000;
$receipt_counter = $receipt_base + 1;

$inserted_count = 0;
$income_count = 0;
$expense_count = 0;
$total_income_amount = 0;
$total_expense_amount = 0;

$stmt_insert = $pdo->prepare("INSERT INTO finance (date, type, amount, description, donor_name, manual_receipt_no, computer_receipt_no, user_id, user_name, is_deleted) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0)");

foreach ($json_data as $row) {
    $manual_no = '#' . $row['final_serial'];
    $date = !empty($row['date']) && strpos($row['date'], '-') !== false ? $row['date'] : date('Y-m-d');
    $type = $row['type'];
    $amount = (float)$row['amount'];
    $desc = trim($row['description']);
    $donor = !empty($row['donor_name']) ? trim($row['donor_name']) : ($type === 'Income' ? $desc : '');

    $comp_receipt_no = null;
    if ($type === 'Income') {
        $comp_receipt_no = $receipt_counter;
        $receipt_counter++;
        $income_count++;
        $total_income_amount += $amount;
    } else {
        $expense_count++;
        $total_expense_amount += $amount;
    }

    $stmt_insert->execute([
        $date,
        $type,
        $amount,
        $desc,
        $donor,
        $manual_no,
        $comp_receipt_no,
        $target_user_id,
        $target_user_name
    ]);
    $inserted_count++;
}

$net_balance = $total_income_amount - $total_expense_amount;

echo "<div style='font-family: Arial, sans-serif; padding: 30px; text-align: center; direction: rtl; max-width: 700px; margin: 40px auto; border: 2px solid #198754; border-radius: 12px; background: #f8fff9;'>";
echo "<h2 style='color: #198754; margin-bottom: 20px;'>✅ پرانا ڈیٹا صاف کر کے تمام 214 انٹریز Tanzeel اکاؤنٹ میں تاریخی ترتیب کے ساتھ کامیابی سے شامل ہو گئیں!</h2>";
echo "<div style='text-align: right; background: #ffffff; padding: 20px; border-radius: 8px; border: 1px solid #c3e6cb; margin-bottom: 20px;'>";
echo "<p style='font-size: 16px; margin: 8px 0;'><b>اکاؤنٹ نام:</b> <span style='color: #0d6efd;'>{$target_user_name}</span> (آئی ڈی: {$target_user_id})</p>";
echo "<p style='font-size: 16px; margin: 8px 0;'><b>آمدن کی انٹریز (رسید نمبرز کے ساتھ):</b> <span style='color: #198754;'>{$income_count}</span> (تاریخی رسیدیں: #" . ($receipt_base + 1) . " تا #" . ($receipt_counter - 1) . ")</p>";
echo "<p style='font-size: 16px; margin: 8px 0;'><b>اخراجات کی انٹریز:</b> <span style='color: #dc3545;'>{$expense_count}</span></p>";
echo "<p style='font-size: 16px; margin: 8px 0;'><b>کل آمدن:</b> <span style='color: #198754;'>Rs. " . number_format($total_income_amount) . "</span></p>";
echo "<p style='font-size: 16px; margin: 8px 0;'><b>کل اخراجات:</b> <span style='color: #dc3545;'>Rs. " . number_format($total_expense_amount) . "</span></p>";
echo "<p style='font-size: 18px; margin: 8px 0; border-top: 1px solid #ccc; pt-2;'><b>خالص بقایا (Balance):</b> <span style='color: #0d6efd;'>Rs. " . number_format($net_balance) . "</span></p>";
echo "<p style='font-size: 16px; margin: 8px 0;'><b>مجموعی کل انٹریز:</b> <b>{$inserted_count}</b></p>";
echo "</div>";
echo "<p><a href='simple_finance.php' style='display: inline-block; background: #198754; color: #fff; padding: 12px 25px; text-decoration: none; border-radius: 6px; font-weight: bold;'>فائنانس / مالیات صفحہ پر جائیں</a></p>";
echo "</div>";
